insert into tests (id, definition) values ('romantic', '{"id":"romantic","slug":"romantik-iliski-testi","name":"İlişki Yapısı Anlık Görünümü","subtitle":"6 boyut · 32 soru · ~7 dakika","inviteCta":"Partnerini davet et","dimensions":{"decision":{"id":"decision","name":"Karar Paylaşımı","short":"Kararlar nasıl ve kimin lehine alınıyor?","index":"power","interpretation":{"yüksek":"Kararlar büyük ölçüde karşılıklı ve paylaşımlı alınıyor; taraflardan birinin sistematik üstünlüğü görünmüyor.","orta":"Kararlar çoğu zaman paylaşılıyor, ancak bazı alanlarda taraflardan biri daha belirleyici olabiliyor.","düşük":"Kararların belirgin biçimde bir tarafta yoğunlaştığı görülüyor. Bu bir ''karar asimetrisi'' işaretidir."}},"domestic":{"id":"domestic","name":"Ev İçi Emek","short":"Fiziksel ev işlerinin dağılımı.","index":"labour","interpretation":{"yüksek":"Fiziksel ev işleri görece dengeli paylaşılıyor.","orta":"Ev işlerinde ölçülü bir dengesizlik var; bazı görevler bir tarafta yoğunlaşıyor olabilir.","düşük":"Fiziksel ev işleri belirgin biçimde bir tarafta toplanmış görünüyor."}},"mental":{"id":"mental","name":"Zihinsel Yük","short":"Planlama ve hatırlama emeğinin dağılımı.","index":"labour","interpretation":{"yüksek":"Planlama ve hatırlama gibi görünmeyen zihinsel yük dengeli dağılmış.","orta":"Zihinsel yükte kısmi bir dengesizlik var; koordinasyon işleri kısmen bir tarafta.","düşük":"Planlama ve koordinasyon (mental load) büyük ölçüde bir tarafın üzerinde yoğunlaşıyor. Ev işleri eşit görünse bile toplam emek eşit olmayabilir."}},"digital":{"id":"digital","name":"Dijital Emek","short":"Araştırma, rezervasyon, koordinasyon emeği.","index":"labour","interpretation":{"yüksek":"Araştırma, rezervasyon ve dijital koordinasyon emeği dengeli paylaşılıyor.","orta":"Dijital koordinasyon emeğinde kısmi bir dengesizlik görünüyor.","düşük":"Dijital koordinasyon emeği (araştırma, rezervasyon, mesajlaşma) belirgin biçimde bir tarafta."}},"social":{"id":"social","name":"Sosyal Özerklik","short":"Bireysel sosyal alanın korunması.","index":"autonomy","interpretation":{"yüksek":"Bireysel sosyal alan güçlü biçimde korunuyor; ilişki bireyselliği kısıtlamıyor.","orta":"Bireysel sosyal alan çoğunlukla korunuyor, ancak bazı durumlarda daralabiliyor.","düşük":"Bireysel sosyal alanın daraldığı görülüyor. Bu düşük algılanan özerklik işaretidir."}},"family":{"id":"family","name":"Aile Sınırları","short":"Ailelerin ilişki üzerindeki etkisi ve sınırlar.","index":"autonomy","interpretation":{"yüksek":"Ailelerle ilişkide dengeli ve sağlıklı sınırlar kurulmuş görünüyor.","orta":"Aile sınırları çoğunlukla dengeli, ancak bazı konularda bir aile daha etkili olabiliyor.","düşük":"Ailelerin ilişki üzerindeki etkisi yüksek ya da dengesiz görünüyor."}}},"indices":{"power":{"id":"power","name":"Güç","desc":"Karar ve etki dengesi."},"labour":{"id":"labour","name":"Emek","desc":"Ev işi, zihinsel ve dijital emeğin dağılımı."},"autonomy":{"id":"autonomy","name":"Özerklik","desc":"Bireysel sosyal alan ve aile sınırları."}},"questions":[{"id":0,"dim":"decision","type":"likert","text":"Önemli kararlarımızda her iki tarafın görüşü yaklaşık eşit ağırlıktadır.","options":[{"label":"Kesinlikle katılıyorum","score":100},{"label":"Katılıyorum","score":75},{"label":"Kararsızım","score":50},{"label":"Katılmıyorum","score":25},{"label":"Kesinlikle katılmıyorum","score":0}]},{"id":1,"dim":"decision","type":"likert_reverse","text":"Bir konuda anlaşamadığımızda genellikle aynı kişi son sözü söyler.","options":[{"label":"Kesinlikle katılıyorum","score":0},{"label":"Katılıyorum","score":25},{"label":"Kararsızım","score":50},{"label":"Katılmıyorum","score":75},{"label":"Kesinlikle katılmıyorum","score":100}]},{"id":2,"dim":"decision","type":"likert_reverse","text":"Partnerimin ihtiyaçları benimkilerden daha sık öncelik kazanır.","options":[{"label":"Kesinlikle katılıyorum","score":0},{"label":"Katılıyorum","score":25},{"label":"Kararsızım","score":50},{"label":"Katılmıyorum","score":75},{"label":"Kesinlikle katılmıyorum","score":100}]},{"id":3,"dim":"decision","type":"balance","text":"Tatil, taşınma gibi büyük kararları çoğunlukla kim verir?","options":[{"label":"Neredeyse her zaman ben","score":0},{"label":"Çoğunlukla ben","score":50},{"label":"Yaklaşık eşit","score":100},{"label":"Çoğunlukla partnerim","score":50},{"label":"Neredeyse her zaman partnerim","score":0}]},{"id":4,"dim":"decision","type":"balance","text":"Büyük harcamalarla ilgili son kararı genellikle kim verir?","options":[{"label":"Neredeyse her zaman ben","score":0},{"label":"Çoğunlukla ben","score":50},{"label":"Yaklaşık eşit","score":100},{"label":"Çoğunlukla partnerim","score":50},{"label":"Neredeyse her zaman partnerim","score":0}]},{"id":5,"dim":"domestic","type":"balance","text":"Yemek hazırlama işini genellikle kim yapar?","options":[{"label":"Neredeyse her zaman ben","score":0},{"label":"Çoğunlukla ben","score":50},{"label":"Yaklaşık eşit","score":100},{"label":"Çoğunlukla partnerim","score":50},{"label":"Neredeyse her zaman partnerim","score":0}]},{"id":6,"dim":"domestic","type":"balance","text":"Ev temizliğini çoğunlukla kim yapar?","options":[{"label":"Neredeyse her zaman ben","score":0},{"label":"Çoğunlukla ben","score":50},{"label":"Yaklaşık eşit","score":100},{"label":"Çoğunlukla partnerim","score":50},{"label":"Neredeyse her zaman partnerim","score":0}]},{"id":7,"dim":"domestic","type":"balance","text":"Çamaşır ve ütü işlerini çoğunlukla kim yapar?","options":[{"label":"Neredeyse her zaman ben","score":0},{"label":"Çoğunlukla ben","score":50},{"label":"Yaklaşık eşit","score":100},{"label":"Çoğunlukla partnerim","score":50},{"label":"Neredeyse her zaman partnerim","score":0}]},{"id":8,"dim":"domestic","type":"balance","text":"Günlük market alışverişini genellikle kim yapar?","options":[{"label":"Neredeyse her zaman ben","score":0},{"label":"Çoğunlukla ben","score":50},{"label":"Yaklaşık eşit","score":100},{"label":"Çoğunlukla partnerim","score":50},{"label":"Neredeyse her zaman par