":"Katılmıyorum","score":75},{"label":"Kesinlikle katılmıyorum","score":100}]},{"id":15,"dim":"mental","type":"likert","text":"Zihinsel yükün (planlama, hatırlama, koordinasyon) aramızdaki dağılımından memnunum.","options":[{"label":"Kesinlikle katılıyorum","score":100},{"label":"Katılıyorum","score":75},{"label":"Kararsızım","score":50},{"label":"Katılmıyorum","score":25},{"label":"Kesinlikle katılmıyorum","score":0}],"satisfactionQuestion":true},{"id":16,"dim":"digital","type":"balance","text":"Restoran, tatil veya etkinlik araştırmalarını çoğunlukla kim yapar?","options":[{"label":"Neredeyse her zaman ben","score":0},{"label":"Çoğunlukla ben","score":50},{"label":"Yaklaşık eşit","score":100},{"label":"Çoğunlukla partnerim","score":50},{"label":"Neredeyse her zaman partnerim","score":0}]},{"id":17,"dim":"digital","type":"balance","text":"Online alışveriş ve rezervasyonları çoğunlukla kim yönetir?","options":[{"label":"Neredeyse her zaman ben","score":0},{"label":"Çoğunlukla ben","score":50},{"label":"Yaklaşık eşit","score":100},{"label":"Çoğunlukla partnerim","score":50},{"label":"Neredeyse her zaman partnerim","score":0}]},{"id":18,"dim":"digital","type":"balance","text":"Ortak sosyal hayatımızla ilgili mesajlaşmaları çoğunlukla kim yürütür?","options":[{"label":"Neredeyse her zaman ben","score":0},{"label":"Çoğunlukla ben","score":50},{"label":"Yaklaşık eşit","score":100},{"label":"Çoğunlukla partnerim","score":50},{"label":"Neredeyse her zaman partnerim","score":0}]},{"id":19,"dim":"digital","type":"balance","text":"Fotoğrafları saklama ve paylaşma işini çoğunlukla kim yapar?","options":[{"label":"Neredeyse her zaman ben","score":0},{"label":"Çoğunlukla ben","score":50},{"label":"Yaklaşık eşit","score":100},{"label":"Çoğunlukla partnerim","score":50},{"label":"Neredeyse her zaman partnerim","score":0}]},{"id":20,"dim":"digital","type":"balance","text":"Ortak takvim ve planları dijital olarak çoğunlukla kim takip eder?","options":[{"label":"Neredeyse her zaman b