insert into tests (id, definition) values ('friendship', '{"id":"friendship","slug":"arkadaslik-iliskisi-testi","name":"Arkadaşlık Yapısı Anlık Görünümü","subtitle":"6 boyut · 31 soru · ~7 dakika","inviteCta":"Arkadaşını davet et","dimensions":{"initiative":{"id":"initiative","name":"İletişim Girişimi","short":"Görüşme ve iletişimi kim başlatıyor?","index":"reciprocity","interpretation":{"yüksek":"İletişimi başlatma sorumluluğu iki taraf arasında dengeli dağılmış; taraflardan birinin sürekli inisiyatif alması gerekmiyor.","orta":"İletişim girişiminde kısmi bir dengesizlik var; bazı dönemlerde bir taraf daha çok inisiyatif alıyor olabilir.","düşük":"İletişimi başlatma büyük ölçüde bir tarafta yoğunlaşmış görünüyor. Bu bir ''girişim asimetrisi'' işaretidir."}},"effort":{"id":"effort","name":"Emek Dengesi","short":"Zaman ve çaba yatırımının dağılımı.","index":"reciprocity","interpretation":{"yüksek":"Zaman ve çaba yatırımı iki taraf arasında dengeli.","orta":"Emek dengesinde ölçülü bir dengesizlik var; bir taraf bazen daha fazla çaba gösteriyor olabilir.","düşük":"Bu arkadaşlığa yatırılan çaba belirgin biçimde bir tarafta toplanmış görünüyor."}},"emotional":{"id":"emotional","name":"Duygusal Destek","short":"Zor zamanlarda dinlenme ve anlaşılma.","index":"support","interpretation":{"yüksek":"Duygusal destek karşılıklı ve güvenli biçimde alışverişte.","orta":"Duygusal destekte kısmi bir dengesizlik var; bazı durumlarda destek tek yönlü kalabiliyor.","düşük":"Duygusal destek belirgin biçimde tek yönlü görünüyor; bu, yük hissi ya da yalnızlaşma riski taşıyabilir."}},"practical":{"id":"practical","name":"Pratik Destek","short":"Yardım isteme/verme ve kaynak paylaşımı.","index":"support","interpretation":{"yüksek":"Pratik yardım ve kaynak paylaşımı dengeli biçimde iki yönlü işliyor.","orta":"Pratik destekte kısmi bir dengesizlik var; yardım isteme/verme bazen tek yönlü olabiliyor.","düşük":"Pratik destek belirgin biçimde bir taraftan diğerine akıyor görünüyor."}},"honesty":{"id":"honesty","name":"Dürüstlük ve Çatışma","short":"Açık iletişim, kırgınlık ve özür dengesi.","index":"trust","interpretation":{"yüksek":"Çatışma ve kırgınlıklar açıkça konuşulabiliyor; güven güçlü görünüyor.","orta":"Dürüstlük ve çatışma yönetiminde kısmi bir zorlanma var; bazı konular konuşulmadan geçiştirilebiliyor.","düşük":"Kırgınlıkların konuşulmadığı ya da özür/geri adımın hep aynı taraftan geldiği görülüyor. Bu, biriken gerilim işareti olabilir."}},"autonomy":{"id":"autonomy","name":"Özerklik","short":"Bağımsız hayata ve diğer ilişkilere saygı.","index":"trust","interpretation":{"yüksek":"Bağımsız hayatlara ve başka ilişkilere saygı güçlü; arkadaşlık kişisel alanı kısıtlamıyor.","orta":"Özerklik çoğunlukla korunuyor, ancak bazı durumlarda sahiplenme ya da tedirginlik görülebiliyor.","düşük":"Bağımsız kararlara ya da diğer ilişkilere karşı belirgin bir tedirginlik/sahiplenme görülüyor. Bu düşük algılanan özerklik işaretidir."}}},"indices":{"reciprocity":{"id":"reciprocity","name":"Karşılıklılık","desc":"Girişim ve emek dengesi."},"support":{"id":"support","name":"Destek","desc":"Duygusal ve pratik destek alışverişi."},"trust":{"id":"trust","name":"Güven ve Sınırlar","desc":"Dürüstlük, çatışma yönetimi ve özerklik."}},"questions":[{"id":0,"dim":"initiative","type":"balance","text":"Buluşma/görüşme teklifini genellikle kim yapar?","options":[{"label":"Neredeyse her zaman ben","score":0},{"label":"Çoğunlukla ben","score":50},{"label":"Yaklaşık eşit","score":100},{"label":"Çoğunlukla arkadaşım","score":50},{"label":"Neredeyse her zaman arkadaşım","score":0}]},{"id":1,"dim":"initiative","type":"balance","text":"Mesajlaşmayı genellikle kim başlatır?","options":[{"label":"Neredeyse her zaman ben","score":0},{"label":"Çoğunlukla ben","score":50},{"label":"Yaklaşık eşit","score":100},{"label":"Çoğunlukla arkadaşım","score":50},{"label":"Neredeyse her zaman arkadaşım","score":0}]},{"id":2,"dim":"initiative","type":"likert","text":"Aramızdaki iletişimin başlatılma s