"whenValue":"under18","band":"düşük","note":"Not: çocuk 18 yaşından küçükse ebeveynin yönlendirici konuşması (öğüt, yönlendirme) yaşa uygun bir ebeveynlik biçimi olabilir; tek başına sorun anlamına gelmez."}]},"emotionalLabour":{"id":"emotionalLabour","name":"Duygusal Emek","short":"Zor anda moral desteği kimden kime akıyor?","index":"labour","interpretation":{"yüksek":"Duygusal destek karşılıklı akıyor; teselli etme emeği tek tarafta yığılmıyor.","orta":"Destek çoğunlukla karşılıklı, ancak bazı dönemlerde bir taraf daha çok veren konumda kalıyor.","düşük":"Duygusal emeğin belirgin biçimde bir tarafta yoğunlaştığı görülüyor."}},"practicalSupport":{"id":"practicalSupport","name":"Pratik Destek","short":"Zaman, para, iş gücü gibi somut yardım nasıl dağılıyor?","index":"labour","interpretation":{"yüksek":"Somut destek (zaman, para, iş gücü) iki yönlü akıyor; yük tek tarafta yığılmıyor.","orta":"Somut destek çoğunlukla karşılıklı, ancak bazı dönemlerde yük bir tarafa kayabiliyor.","düşük":"Pratik yükün belirgin biçimde bir tarafta toplandığı görülüyor."}},"trust":{"id":"trust","name":"Güven ve Kontrol","short":"İlişki güvenle mi, kontrolle mi yürüyor?","index":"autonomy","interpretation":{"yüksek":"Güven baskın; sürekli kontrol ya da denetleme ihtiyacı hissedilmiyor.","orta":"Güven çoğunlukla var, ancak bazı konularda kontrol öne çıkabiliyor.","düşük":"Kontrol eğilimi belirgin; güven yerine sürekli denetim öne çıkıyor görünüyor."}},"privacy":{"id":"privacy","name":"Özel Alan","short":"Kişisel sınırlar ve mahremiyet korunuyor mu?","index":"autonomy","interpretation":{"yüksek":"Kişisel alan ve mahremiyet büyük ölçüde korunuyor.","orta":"Özel alan çoğunlukla korunuyor, ancak zaman zaman ihlal edilebiliyor.","düşük":"Kişisel alana ya da mahremiyete belirgin bir taşma görülüyor."}}},"indices":{"power":{"id":"power","name":"Güç","desc":"Karar mekanizması ve konuşmadaki söz dengesi."},"labour":{"id":"labour","name":"Emek","desc":"Duygusal ve pratik desteğin dağılımı."},"autono