insert into tests (id, definition) values ('roommate', '{"id":"roommate","slug":"ev-arkadasligi-testi","name":"Ev Arkadaşlığı Yapısı Anlık Görünümü","subtitle":"6 boyut · 31 soru · ~7 dakika","inviteCta":"Ev arkadaşını davet et","dimensions":{"chores":{"id":"chores","name":"Ev İşi Dağılımı","short":"Temizlik, çöp, bulaşık gibi günlük işler nasıl paylaşılıyor?","index":"labour","interpretation":{"yüksek":"Ev işleri dengeli paylaşılıyor; günlük yük tek tarafta yığılmıyor.","orta":"Ev işlerinin dağılımında ölçülü bir dengesizlik var; bazı işler bir tarafta daha çok toplanabiliyor.","düşük":"Günlük ev işlerinin belirgin biçimde bir tarafta yoğunlaştığı görülüyor. Bu bir ''iş yükü asimetrisi'' işaretidir."}},"expenses":{"id":"expenses","name":"Ortak Masraf Dengesi","short":"Kira, fatura, market gibi ortak giderler adil paylaşılıyor mu?","index":"labour","interpretation":{"yüksek":"Ortak masraflar adil ve düzenli biçimde paylaşılıyor.","orta":"Masraf paylaşımında kısmi bir dengesizlik var; takip ya da hatırlatma bazen tek tarafa kalabiliyor.","düşük":"Ortak masrafların takibi ve karşılanması belirgin biçimde bir tarafta toplanmış görünüyor."}},"standards":{"id":"standards","name":"Düzen ve Temizlik Uyumu","short":"Temizlik ve düzen beklentileri birbirine ne kadar yakın?","index":"harmony","interpretation":{"yüksek":"Temizlik ve düzen beklentileri büyük ölçüde örtüşüyor; ortak bir orta yol bulunabiliyor.","orta":"Beklentilerde kısmi bir uyumsuzluk var; bazı konularda taraflardan biri diğerine uyum sağlamak zorunda kalıyor.","düşük":"Temizlik/düzen standartları belirgin biçimde uyuşmuyor; uyum sağlama yükü tek tarafta görünüyor."}},"communication":{"id":"communication","name":"İletişim ve Çatışma Çözümü","short":"Ev ile ilgili sorunlar ve anlaşmazlıklar nasıl konuşuluyor?","index":"harmony","interpretation":{"yüksek":"Ev ile ilgili sorunlar doğrudan ve açıkça konuşulabiliyor; gerginlikler birikmiyor.","orta":"İletişim çoğunlukla açık, ancak bazı rahatsızlıklar dile getirilmeden içte kalabiliyor.","düşük":"Rahatsızlıkların konuşulmadığı ya da görmezden gelindiği bir örüntü görülüyor. Bu, biriken gerilim işareti olabilir."}},"guests":{"id":"guests","name":"Misafir ve Ortak Alan","short":"Misafir ağırlama ve ortak alan kullanımı nasıl belirleniyor?","index":"boundaries","interpretation":{"yüksek":"Misafir ve ortak alan kullanımında karşılıklı gözetilen, netleşmiş bir anlayış var.","orta":"Ortak alan kullanımı çoğunlukla gözetiliyor, ancak zaman zaman gerginlik yaratabiliyor.","düşük":"Misafir ağırlama ya da ortak alan kullanımı belirgin bir rahatsızlık ya da tek taraflı belirlenme kaynağı görünüyor."}},"privacy":{"id":"privacy","name":"Sessizlik ve Kişisel Alan","short":"Gürültü, mahremiyet ve kişisel eşyalara saygı nasıl?","index":"boundaries","interpretation":{"yüksek":"Kişisel alan, eşyalar ve sessizlik ihtiyacı büyük ölçüde gözetiliyor.","orta":"Kişisel alana saygı çoğunlukla var, ancak zaman zaman ihlal edilebiliyor.","düşük":"Kişisel alana, mahremiyete ya da sessizlik ihtiyacına belirgin bir taşma görülüyor."}}},"indices":{"labour":{"id":"labour","name":"Emek","desc":"Ev işleri ve ortak masrafların dağılımı."},"harmony":{"id":"harmony","name":"Uyum","desc":"Düzen standartları ve iletişim/çatışma çözümü."},"boundaries":{"id":"boundaries","name":"Sınırlar","desc":"Misafir, ortak alan ve kişisel alan dengesi."}},"questions":[{"id":0,"dim":"chores","type":"likert","text":"Ev işleri (temizlik, çöp, bulaşık) aramızda adil paylaşılıyor.","options":[{"label":"Kesinlikle katılıyorum","score":100},{"label":"Katılıyorum","score":75},{"label":"Kararsızım","score":50},{"label":"Katılmıyorum","score":25},{"label":"Kesinlikle katılmıyorum","score":0}]},{"id":1,"dim":"chores","type":"likert_reverse","text":"Ev işlerinin çoğunu ben üstleniyorum, karşılığını göremiyorum.","options":[{"label":"Kesinlikle katılıyorum","score":0},{"label":"Katılıyorum","score":25},{"label":"Kararsızım","score":50},{"label":"Katılmıyorum","score":75},{"label":"Kesinlikl