insert into tests (id, definition) values ('work', '{"id":"work","slug":"is-iliskisi-testi","name":"İş İlişkisi Yapısı Anlık Görünümü","subtitle":"6 boyut · 31 soru · ~7 dakika","inviteCta":"Yöneticini ya da çalışanını davet et","contextQuestions":[{"id":"role","text":"Bu testi kim dolduruyor?","options":[{"label":"Yönetici","value":"manager"},{"label":"Çalışan","value":"employee"}]}],"disclaimerNote":"İş ilişkisinde bazı asimetriler (ör. yöneticinin son sözü olması) meşru hiyerarşinin parçasıdır; her asimetri sorun anlamına gelmez.","dimensions":{"decision":{"id":"decision","name":"Karar Payı","short":"Kararlarda sesin ne kadar duyuluyor?","index":"power","interpretation":{"yüksek":"Kararlar büyük ölçüde birlikte alınıyor; söz hakkı ve yetki net biçimde paylaşılmış görünüyor.","orta":"Kararlar çoğunlukla paylaşılıyor, ancak bazı konularda söz hakkı tek tarafta yoğunlaşabiliyor.","düşük":"Kararların belirgin biçimde tek tarafta toplandığı görülüyor. Bu bir ''karar asimetrisi'' işaretidir."},"conditionalNotes":[{"contextQuestionId":"role","whenValue":"employee","band":"düşük","note":"Not: yöneticinin son sözü olması meşru bir hiyerarşik yapının parçası olabilir; bu tek başına sorun anlamına gelmez."}]},"feedback":{"id":"feedback","name":"Geri Bildirim Yönü","short":"Geri bildirim tek yönlü mü, karşılıklı mı akıyor?","index":"power","interpretation":{"yüksek":"Geri bildirim iki yönlü akıyor; taraflar birbirine açıkça geri bildirim verebiliyor.","orta":"Geri bildirim çoğunlukla akıyor, ancak yön çoğu zaman aynı taraftan diğerine doğru.","düşük":"Geri bildirim büyük ölçüde tek yönlü görünüyor. Bu, sessiz kalan tarafın görünmez kaldığı bir yapı olabilir."},"conditionalNotes":[{"contextQuestionId":"role","whenValue":"employee","band":"düşük","note":"Not: hiyerarşik yapılarda geri bildirimin ağırlıklı olarak yönetici-çalışan yönünde akması beklenen bir durum olabilir; tek başına sorun anlamına gelmez."}]},"workload":{"id":"workload","name":"İş Yükü Adaleti","short":"İş yükü ve sorumluluk dağılımı adil mi?","index":"labour","interpretation":{"yüksek":"İş yükü ve sorumluluk dağılımı dengeli algılanıyor.","orta":"İş yükünde ölçülü bir dengesizlik var; bazı dönemlerde yük bir tarafa kayabiliyor.","düşük":"İş yükünün belirgin biçimde bir tarafta yoğunlaştığı görülüyor."}},"recognition":{"id":"recognition","name":"Görünürlük ve Takdir","short":"Emek fark ediliyor, katkı takdir görüyor mu?","index":"labour","interpretation":{"yüksek":"Emek ve katkı görülüyor, karşılığında takdir geliyor.","orta":"Katkı çoğunlukla fark ediliyor, ancak takdir düzenli ya da tutarlı değil.","düşük":"Emeğin görünmediği ya da takdirin eksik kaldığı bir yapı öne çıkıyor."}},"trust":{"id":"trust","name":"Güven ve Mikro-yönetim","short":"İş nasıl takip ediliyor: güvenle mi, kontrolle mi?","index":"autonomy","interpretation":{"yüksek":"İş güvenle devrediliyor; sürekli kontrol ihtiyacı hissedilmiyor.","orta":"Güven çoğunlukla var, ancak bazı alanlarda yakın takip ya da kontrol öne çıkabiliyor.","düşük":"Mikro-yönetim eğilimi belirgin; iş, güven yerine sürekli kontrolle takip ediliyor görünüyor."}},"boundaries":{"id":"boundaries","name":"Sınırlar","short":"Mesai dışı zaman ve kişisel alan korunuyor mu?","index":"autonomy","interpretation":{"yüksek":"Mesai dışı zaman ve kişisel alan büyük ölçüde korunuyor.","orta":"Sınırlar çoğunlukla korunuyor, ancak zaman zaman ihlal edilebiliyor.","düşük":"Mesai dışı zamana ya da kişisel alana belirgin bir taşma görülüyor."}}},"indices":{"power":{"id":"power","name":"Güç","desc":"Karar ve geri bildirim yönünün dengesi."},"labour":{"id":"labour","name":"Emek","desc":"İş yükü dağılımı ve emeğin görünürlüğü."},"autonomy":{"id":"autonomy","name":"Özerklik","desc":"Güven, kontrol ve kişisel sınırlar."}},"questions":[{"id":0,"dim":"decision","type":"likert","text":"Bu iş ilişkisinde önemli kararlar genellikle birlikte alınır.","options":[{"label":"Kesinlikle katılıyorum","score":100},{"label":"Katılıyorum","score":75},{"label":"Kararsızım"